import re

class SemVer:
    def __init__(self, version_str: str):
        self.original = version_str
        self.major = 0
        self.minor = 0
        self.patch = 0
        self.pre_release = []

        self._parse(version_str)

    def _parse(self, version_str: str):
        v = version_str
        if v.startswith('v'):
            v = v[1:]

        main_part = v.split('+')[0]

        if '-' in main_part:
            core_part, pre_part = main_part.split('-', 1)
            if not pre_part:
                raise ValueError("Empty pre-release identifier")
            self.pre_release = self._parse_identifiers(pre_part, is_pre_release=True)
        else:
            core_part = main_part

        core_parts = core_part.split('.')
        if len(core_parts) != 3:
            raise ValueError("Core version must be MAJOR.MINOR.PATCH")

        for i, part in enumerate(core_parts):
            if not part.isdigit():
                raise ValueError("Core parts must be numeric")
            if len(part) > 1 and part[0] == '0':
                raise ValueError("Leading zeros not allowed in core version")

            val = int(part)
            if i == 0: self.major = val
            elif i == 1: self.minor = val
            else: self.patch = val

    def _parse_identifiers(self, part_str: str, is_pre_release: bool) -> list:
        idents = part_str.split('.')
        parsed_idents = []
        for ident in idents:
            if not ident:
                raise ValueError("Empty identifier in version")

            if ident.isdigit():
                if len(ident) > 1 and ident[0] == '0':
                    raise ValueError("Leading zeros not allowed in numeric identifiers")
                parsed_idents.append(int(ident))
            else:
                parsed_idents.append(ident)
        return parsed_idents

    def __lt__(self, other):
        if not isinstance(other, SemVer):
            return NotImplemented

        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch

        if not self.pre_release and other.pre_release:
            return False
        if self.pre_release and not other.pre_release:
            return True
        if not self.pre_release and not other.pre_release:
            return False

        for s_ident, o_ident in zip(self.pre_release, other.pre_release):
            if s_ident == o_ident:
                continue

            if isinstance(s_ident, int) and isinstance(o_ident, int):
                return s_ident < o_ident
            if isinstance(s_ident, int) and not isinstance(o_ident, int):
                return True
            if not isinstance(s_ident, int) and isinstance(o_ident, int):
                return False
            return str(s_ident) < str(o_ident)

        return len(self.pre_release) < len(other.pre_release)

    def __eq__(self, other):
        if not isinstance(other, SemVer):
            return NotImplemented
        return (self.major == other.major and 
                self.minor == other.minor and 
                self.patch == other.patch and 
                self.pre_release == other.pre_release)

    def __gt__(self, other):
        if not isinstance(other, SemVer):
            return NotImplemented
        return not self.__lt__(other) and not self.__eq__(other)

def compare(a: str, b: str) -> int:
    va = SemVer(a)
    vb = SemVer(b)
    if va < vb:
        return -1
    if va > vb:
        return 1
    return 0

def sort_versions(versions: list[str]) -> list[str]:
    return sorted(versions, key=lambda v: SemVer(v))
